495	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
496	        owner.setCustomerCode(generateCustomerCode(owner));
497	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
498	        owner.setHouseholdId(householdId(owner));
499	        owner.setNamesakeCount(countNamesakes(owner));
500	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
501	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
502	        if (declaredMember) {
503	            owner.setPossibleDuplicate(false);
504	            owner.setPossibleDuplicateOf(null);
505	        } else {
506	            assignPossibleDuplicate(owner);
507	        }
508	    }
509	
510	    /**
511	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
512	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
513	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
514	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
515	     * matching owner's id. Runs before save, against the existing owner population.
516	     */
517	    private void assignPossibleDuplicate(Owner owner) {
518	        Integer matchId = findPossibleDuplicateOf(owner);
519	        owner.setPossibleDuplicate(matchId != null);
520	        owner.setPossibleDuplicateOf(matchId);
521	    }
522	
523	    /**
524	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
525	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
526	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
527	     * with the same last name and postcode but different telephones differ in key and so match here,
528	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
529	     * the lowest id is returned. An owner without a postcode never matches.
530	     */
531	    private Integer findPossibleDuplicateOf(Owner owner) {
532	        String postcode = owner.getPostcode();
533	        if (postcode == null) {
534	            return null;
535	        }
536	        String soundex = soundex(owner.getLastName());
537	        String identityKey = owner.getIdentityKey();
538	        return this.clinicService.findAllOwners().stream()
539	            .filter(existing -> !existing.isDeleted())
540	            .filter(existing -> existing.getId() != null
541	                && postcode.equals(existing.getPostcode())
542	                && soundex(existing.getLastName()).equals(soundex)
543	                && !identityKey.equals(existing.getIdentityKey()))
544	            .map(Owner::getId)
545	            .min(Integer::compareTo)
546	            .orElse(null);
547	    }
548	
549	    /**
550	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
551	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
552	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
553	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
554	     * region and the (telephone, last name) pair; only when the computed code collides with an
555	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
556	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
557	     */
558	    private String generateCustomerCode(Owner owner) {
559	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
560	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
561	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
562	        String base = owner.getRegion() + "-" + hash8;
563	        return deduplicateCustomerCode(base);
564	    }
565	
566	    /**
567	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
568	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
569	     * {@code n} of 2 or more that yields a code no existing owner carries.
570	     */
571	    private String deduplicateCustomerCode(String base) {
572	        Set<String> existing = this.clinicService.findAllOwners().stream()
573	            .map(Owner::getCustomerCode)
574	            .filter(code -> code != null)
575	            .collect(java.util.stream.Collectors.toSet());
576	        if (!existing.contains(base)) {
577	            return base;
578	        }
579	        int n = 2;
580	        while (existing.contains(base + "-" + n)) {
581	            n++;
